mapper.select:
SELECT MOMENT_ID, USER_ID, CONTENT_ID, YOUTUBE_ID, START_TIME, END_TIME, MEMO, CREATED_AT, UPDATED_AT
FROM MOMENT
WHERE USER_ID = #{userId} AND DEL_YN = 'N'

    AND CONTENT_ID = #{contentId}


    AND YOUTUBE_ID = #{youtubeId}


    AND (CREATED_AT < #{cursorCreatedAt}
        OR (CREATED_AT = #{cursorCreatedAt} AND MOMENT_ID < #{cursorMomentId}))

ORDER BY CREATED_AT DESC, MOMENT_ID DESC
FETCH NEXT #{limit} ROWS ONLY
